#!/bin/sh
set -eu

home_dir=${ARIA2_HOME:-/var/lib/aria2}
config_dir=${ARIA2_CONFIG_DIR:-$home_dir/.config/aria2}
config_file=${ARIA2_CONFIG_FILE:-$config_dir/aria2.conf}
session_file=${ARIA2_SESSION_FILE:-$config_dir/session.lock}
example_config=/etc/aria2/aria2.conf.example

mkdir -p "$home_dir" "$config_dir" "$(dirname "$session_file")"
touch "$session_file"

if [ ! -f "$config_file" ]; then
    install -m 0644 "$example_config" "$config_file"
fi

export HOME=$home_dir
cd "$home_dir"

exec /usr/bin/aria2c --conf-path="$config_file"

